import math

def f(n):
    """Computes f(n), the largest odd divisor of n."""
    if n <= 0:
        return 0 # Should not happen based on problem description
    while n % 2 == 0:
        n //= 2
    return n

def check_condition(u, v):
    """
    Checks if the condition f(u+k+v) - f(u+k) is a multiple of 4
    for all k in {0, 1, ..., v-1}.
    """
    for k in range(v):
        n = u + k
        n_plus_v = u + k + v

        diff = f(n_plus_v) - f(n)

        if diff % 4 != 0:
            return False
    return True

def find_smallest_u(v, u_max=500):
    """Finds the smallest u <= u_max satisfying the condition for a given v."""
    for u in range(1, u_max + 1):
        if check_condition(u, v):
            return u
    return None

# List of odd integers v to check up to 25
V_values = list(range(1, 26, 2))

results = {}
print("Starting search...")

for v in V_values:
    print(f"Checking v = {v}...")
    u_min = find_smallest_u(v)
    results[v] = u_min

print("\n--- Search Complete ---")
for v, u_min in results.items():
    print(f"v={v}: smallest u = {u_min if u_min is not None else 'None'}")

